const raw = $input.first().json || {};
const data = (raw.query && typeof raw.query === 'object' && !Array.isArray(raw.query)) ? raw.query : raw;

const query = String(data.query || raw.query || '').trim();
const topKRaw = parseInt(data.top_k || raw.top_k, 10);
const topK = Math.max(1, Math.min(Number.isFinite(topKRaw) ? topKRaw : 5, 10));
const vendor = String(data.vendor || raw.vendor || '').trim();

if (!query) {
  return [{ json: { error: 'query es requerido', skip: true, found: false, count: 0, results: [] } }];
}

return [{ json: { query, topK, vendor } }];

const emb = $json.embedding;
if (!Array.isArray(emb) || emb.length !== 768) {
  return [{ json: { error: `embedding inválido (len=${emb ? emb.length : 0})`, skip: true } }];
}
const literal = '[' + emb.join(',') + ']';
const orig = $('Normalize Input').first().json;
return [{ json: { vector_literal: literal, topK: orig.topK, vendor: orig.vendor, query: orig.query } }];

const rows = $input.all().map(i => i.json);
const input = $('Normalize Input').first().json;
const validRows = rows.filter(r => r && r.chunk_text);
const limited = validRows.slice(0, input.topK || 5);

if (!limited.length) {
  return [{ json: { found: false, count: 0, total_found: 0, message: `Sin documentos relevantes para '${input.query}'.`, query: input.query, results: [] } }];
}

return [{ json: {
  found: true,
  count: limited.length,
  total_found: validRows.length,
  query: input.query,
  results: limited.map(r => ({
    similarity: Number(r.similarity).toFixed(3),
    vendor: r.vendor,
    title: r.title,
    category: r.category_hint,
    url: r.source_url,
    text: String(r.chunk_text || '').substring(0, 500)
  }))
} }];
